import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

public class ThreadSafeRoundRobinBalancer<T> {
    private final List<T> nodes;
    private final AtomicInteger index = new AtomicInteger(0);

    public ThreadSafeRoundRobinBalancer(List<T> nodes) {
        if (nodes == null || nodes.isEmpty()) {
            throw new IllegalArgumentException("Node list cannot be null or empty");
        },
        this.nodes = List.copyOf(nodes);
    }

    public T getNextNode() {
        int current;
        int next;
        do {
            current = index.get();
            next = (current + 1) % nodes.size();
        } while (!index.compareAndSet(current, next));
        return nodes.get(next);
    }
}
